//! Loopback OpenAI-compatible endpoint backed by either official API key or
//! the signed-in chat.deepseek.com session.
//!
//! Other apps on the phone talk to `http://127.0.0.1:<port>/v1` with a key
//! generated by this app. Nothing is exposed outside the device.

use std::io::{Cursor, Read, Write};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;
use std::thread::{self, JoinHandle};
use std::time::Duration;

use serde_json::{json, Value};
use tiny_http::{Header, Method, Request, Response, Server, StatusCode};

use crate::api::{Api, Delta};
use crate::types::{now_ms, Error, ErrorKind, Message, Usage, MODEL_ID};
use crate::web::{prompt as web_prompt, WebApi, WebDelta};

const MAX_BODY: u64 = 8 * 1024 * 1024;

#[derive(Clone)]
pub enum Backend {
    Api(Api),
    Web(WebApi),
}

pub struct LocalServer {
    shutdown: Arc<AtomicBool>,
    port: u16,
    key: String,
    handle: Option<JoinHandle<()>>,
    unix_handle: Option<JoinHandle<()>>,
    unix_path: Option<PathBuf>,
}

impl LocalServer {
    pub fn start(
        backend: Backend,
        key: String,
        port: u16,
        unix_path: Option<PathBuf>,
    ) -> Result<Self, Error> {
        let server = Server::http(("127.0.0.1", port)).map_err(|e| {
            Error::new(
                ErrorKind::Io,
                format!("Не удалось открыть порт {port}: {e}"),
            )
        })?;
        let actual_port = server
            .server_addr()
            .to_ip()
            .map(|addr| addr.port())
            .unwrap_or(port);

        #[cfg(unix)]
        let unix_server = match unix_path.as_ref() {
            Some(path) => {
                let _ = std::fs::remove_file(path);
                let server = Server::http_unix(path).map_err(|e| {
                    Error::new(
                        ErrorKind::Io,
                        format!("Не удалось открыть Unix-сокет: {e}"),
                    )
                })?;
                #[cfg(unix)]
                {
                    use std::os::unix::fs::PermissionsExt;
                    let _ = std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600));
                }
                Some(server)
            }
            None => None,
        };
        #[cfg(not(unix))]
        let unix_server: Option<Server> = None;

        let shutdown = Arc::new(AtomicBool::new(false));
        let flag = Arc::clone(&shutdown);
        let backend = Arc::new(backend);
        let worker_key = key.clone();
        let handle = spawn_accept(
            server,
            Arc::clone(&backend),
            worker_key.clone(),
            Arc::clone(&flag),
            "local-api-accept",
        )?;
        let unix_handle = match unix_server {
            Some(server) => match spawn_accept(
                server,
                backend,
                worker_key,
                flag,
                "local-api-unix",
            ) {
                Ok(handle) => Some(handle),
                Err(e) => {
                    shutdown.store(true, Ordering::Relaxed);
                    let _ = handle.join();
                    if let Some(path) = unix_path.as_ref() {
                        let _ = std::fs::remove_file(path);
                    }
                    return Err(e);
                }
            },
            None => None,
        };

        Ok(Self {
            shutdown,
            port: actual_port,
            key,
            handle: Some(handle),
            unix_handle,
            unix_path,
        })
    }

    pub fn port(&self) -> u16 {
        self.port
    }

    pub fn key(&self) -> &str {
        &self.key
    }

    pub fn stop(&mut self) {
        self.shutdown.store(true, Ordering::Relaxed);
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
        if let Some(handle) = self.unix_handle.take() {
            let _ = handle.join();
        }
        if let Some(path) = self.unix_path.take() {
            let _ = std::fs::remove_file(path);
        }
    }
}

impl Drop for LocalServer {
    fn drop(&mut self) {
        self.stop();
    }
}

fn spawn_accept(
    server: Server,
    backend: Arc<Backend>,
    worker_key: String,
    flag: Arc<AtomicBool>,
    name: &str,
) -> Result<JoinHandle<()>, Error> {
    thread::Builder::new()
        .name(name.into())
        .spawn(move || {
            while !flag.load(Ordering::Relaxed) {
                match server.recv_timeout(Duration::from_millis(200)) {
                    Ok(Some(request)) => {
                        let backend = Arc::clone(&backend);
                        let key = worker_key.clone();
                        thread::spawn(move || handle_request(request, &backend, &key));
                    }
                    Ok(None) => {}
                    Err(_) => break,
                }
            }
        })
        .map_err(|e| Error::new(ErrorKind::Io, format!("Сервер не стартовал: {e}")))
}

fn handle_request(mut request: Request, backend: &Backend, key: &str) {
    let is_post = *request.method() == Method::Post;
    let is_get = *request.method() == Method::Get;
    let is_options = *request.method() == Method::Options;
    let path = request
        .url()
        .split('?')
        .next()
        .unwrap_or("/")
        .to_string();

    if is_options {
        let _ = request.respond(cors(Response::empty(204)));
        return;
    }
    if !authorized(&request, key) {
        let _ = request.respond(json_response(
            401,
            &json!({"error": {"message": "Invalid API key", "type": "invalid_request_error", "code": "invalid_api_key"}}),
        ));
        return;
    }

    match (is_get, is_post, path.as_str()) {
        (true, _, "/health") => {
            let _ = request.respond(json_response(200, &json!({"status": "ok"})));
        }
        (true, _, "/v1/models" | "/models") => {
            let _ = request.respond(json_response(
                200,
                &json!({
                    "object": "list",
                    "data": [
                        {"id": MODEL_ID, "object": "model", "owned_by": "deepseek"},
                        {"id": "deepseek-v4-pro", "object": "model", "owned_by": "deepseek"}
                    ]
                }),
            ));
        }
        (_, true, "/v1/chat/completions" | "/chat/completions") => {
            let mut body = String::new();
            if request
                .as_reader()
                .take(MAX_BODY)
                .read_to_string(&mut body)
                .is_err()
            {
                let _ = request.respond(json_response(400, &error_body("unreadable body")));
                return;
            }
            let parsed: Value = match serde_json::from_str(&body) {
                Ok(v) => v,
                Err(_) => {
                    let _ = request.respond(json_response(400, &error_body("invalid JSON")));
                    return;
                }
            };
            let chat = match ChatRequest::parse(&parsed) {
                Ok(c) => c,
                Err(message) => {
                    let _ = request.respond(json_response(400, &error_body(&message)));
                    return;
                }
            };

            if chat.stream {
                respond_stream(request, backend, chat);
            } else {
                match complete(backend, &chat) {
                    Ok(response) => {
                        let _ = request.respond(json_response(200, &response));
                    }
                    Err(e) => {
                        let _ = request.respond(json_response(
                            status_for(&e),
                            &error_body(&e.message),
                        ));
                    }
                }
            }
        }
        _ => {
            let _ = request.respond(json_response(404, &error_body("not found")));
        }
    }
}

fn complete(backend: &Backend, chat: &ChatRequest) -> Result<Value, Error> {
    let mut content = String::new();
    let mut reasoning = String::new();
    let mut usage: Option<Usage> = None;

    match backend {
        Backend::Api(api) => accumulate_api(api, chat, &mut content, &mut reasoning, &mut usage)?,
        Backend::Web(web) => accumulate_web(web, chat, &mut content, &mut reasoning)?,
    }

    let mut message = json!({"role": "assistant", "content": content});
    if !reasoning.is_empty() {
        message["reasoning_content"] = json!(reasoning);
    }
    let usage_value = match usage {
        Some(u) => json!({
            "prompt_tokens": u.prompt_tokens,
            "completion_tokens": u.completion_tokens,
            "total_tokens": u.total_tokens
        }),
        None => Value::Null,
    };
    Ok(json!({
        "id": new_id(),
        "object": "chat.completion",
        "created": now_ms() / 1000,
        "model": chat.model,
        "choices": [{"index": 0, "message": message, "finish_reason": "stop"}],
        "usage": usage_value
    }))
}

fn accumulate_api(
    api: &Api,
    chat: &ChatRequest,
    content: &mut String,
    reasoning: &mut String,
    usage: &mut Option<Usage>,
) -> Result<(), Error> {
    let cancel = AtomicBool::new(false);
    api.stream_chat(
        &chat.messages,
        &chat.model,
        chat.thinking,
        &chat.effort,
        &cancel,
        &mut |delta| {
            match delta {
                Delta::Content(s) => content.push_str(&s),
                Delta::Reasoning(s) => reasoning.push_str(&s),
                Delta::Usage(u) => *usage = Some(u),
            }
            Ok(())
        },
    )
    .map(|_| ())
}

fn accumulate_web(
    web: &WebApi,
    chat: &ChatRequest,
    content: &mut String,
    reasoning: &mut String,
) -> Result<(), Error> {
    let cancel = AtomicBool::new(false);
    let prompt = web_prompt(&chat.messages);
    let session = web.create_session()?;
    let result = web.stream_completion(
        &session,
        None,
        &prompt,
        Some(web_model(&chat.model)),
        chat.thinking,
        false,
        &[],
        &cancel,
        &mut |delta| {
            match delta {
                WebDelta::Answer(s) => content.push_str(&s),
                WebDelta::Reasoning(s) => reasoning.push_str(&s),
            }
            Ok(())
        },
    );
    let _ = web.delete_session(&session);
    result.map(|_| ())
}

fn respond_stream(request: Request, backend: &Backend, chat: ChatRequest) {
    // Web mode needs a server-side session before the first byte goes out.
    let web_session = match backend {
        Backend::Web(web) => match web.create_session() {
            Ok(session) => Some(session),
            Err(e) => {
                let _ = request.respond(json_response(status_for(&e), &error_body(&e.message)));
                return;
            }
        },
        Backend::Api(_) => None,
    };

    // tiny_http buffers a Response body; SSE needs a raw writer we can flush.
    let mut writer = request.into_writer();
    let head = concat!(
        "HTTP/1.1 200 OK\r\n",
        "Content-Type: text/event-stream\r\n",
        "Cache-Control: no-cache\r\n",
        "Transfer-Encoding: chunked\r\n",
        "Connection: close\r\n",
        "Access-Control-Allow-Origin: *\r\n",
        "Access-Control-Allow-Headers: authorization, content-type\r\n",
        "\r\n"
    );
    if writer.write_all(head.as_bytes()).is_err() || writer.flush().is_err() {
        return;
    }

    let backend = backend.clone();
    let model = chat.model.clone();
    thread::spawn(move || {
        let mut sink = SseSink {
            writer,
            id: new_id(),
            created: now_ms() / 1000,
            model,
        };
        if sink.event(json!({"role": "assistant", "content": ""}), None).is_err() {
            return;
        }

        let cancel = AtomicBool::new(false);
        let result: Result<Option<Usage>, Error> = match &backend {
            Backend::Api(api) => api.stream_chat(
                &chat.messages,
                &chat.model,
                chat.thinking,
                &chat.effort,
                &cancel,
                &mut |delta| sink.api_delta(delta),
            ),
            Backend::Web(web) => {
                let session = web_session.clone().unwrap_or_default();
                let prompt = web_prompt(&chat.messages);
                let result = web
                    .stream_completion(
                        &session,
                        None,
                        &prompt,
                        Some(web_model(&chat.model)),
                        chat.thinking,
                        false,
                        &[],
                        &cancel,
                        &mut |delta| sink.web_delta(delta),
                    )
                    .map(|_| None);
                let _ = web.delete_session(&session);
                result
            }
        };

        if let Err(e) = &result {
            if e.kind != ErrorKind::Cancelled {
                sink.error(e);
            }
        }
        sink.finish();
    });
}

struct SseSink {
    writer: Box<dyn Write + Send>,
    id: String,
    created: u64,
    model: String,
}

impl SseSink {
    fn event(&mut self, delta: Value, finish: Option<&str>) -> Result<(), Error> {
        let payload = json!({
            "id": self.id,
            "object": "chat.completion.chunk",
            "created": self.created,
            "model": self.model,
            "choices": [{"index": 0, "delta": delta, "finish_reason": finish}]
        });
        let line = format!("data: {payload}\n\n");
        self.write_chunk(line.as_bytes())
    }

    fn api_delta(&mut self, delta: Delta) -> Result<(), Error> {
        match delta {
            Delta::Content(s) => self.event(json!({ "content": s }), None),
            Delta::Reasoning(s) => self.event(json!({ "reasoning_content": s }), None),
            Delta::Usage(_) => Ok(()),
        }
    }

    fn web_delta(&mut self, delta: WebDelta) -> Result<(), Error> {
        match delta {
            WebDelta::Answer(s) => self.event(json!({ "content": s }), None),
            WebDelta::Reasoning(s) => self.event(json!({ "reasoning_content": s }), None),
        }
    }

    fn error(&mut self, error: &Error) {
        let payload = json!({"error": {"message": error.message, "type": "upstream_error", "code": error.kind.code()}});
        let line = format!("data: {payload}\n\n");
        let _ = self.write_chunk(line.as_bytes());
    }

    fn finish(&mut self) {
        let _ = self.event(json!({}), Some("stop"));
        let _ = self.write_chunk(b"data: [DONE]\n\n");
        let _ = self.writer.write_all(b"0\r\n\r\n");
        let _ = self.writer.flush();
    }

    fn write_chunk(&mut self, bytes: &[u8]) -> Result<(), Error> {
        let header = format!("{:x}\r\n", bytes.len());
        self.writer
            .write_all(header.as_bytes())
            .and_then(|_| self.writer.write_all(bytes))
            .and_then(|_| self.writer.write_all(b"\r\n"))
            .and_then(|_| self.writer.flush())
            .map_err(|_| Error::new(ErrorKind::Cancelled, "Клиент отключился"))
    }
}

struct ChatRequest {
    messages: Vec<Message>,
    model: String,
    thinking: bool,
    effort: String,
    stream: bool,
}

impl ChatRequest {
    fn parse(value: &Value) -> Result<Self, String> {
        let items = value
            .get("messages")
            .and_then(Value::as_array)
            .ok_or_else(|| "messages is required".to_string())?;

        let mut messages = Vec::new();
        for item in items {
            let role = item.get("role").and_then(Value::as_str).unwrap_or("user");
            if !matches!(role, "system" | "user" | "assistant") {
                continue;
            }
            let content = content_text(item.get("content"));
            if content.is_empty() {
                continue;
            }
            messages.push(Message {
                role: role.to_string(),
                content,
                reasoning: String::new(),
                sources: Vec::new(),
                images: Vec::new(),
                ts: 0,
            });
        }
        if messages.is_empty() {
            return Err("messages are empty".to_string());
        }

        let model = match value.get("model").and_then(Value::as_str) {
            Some("deepseek-v4-pro") => "deepseek-v4-pro",
            _ => MODEL_ID,
        };
        // Local API is fast by default: reasoning is opt-in. Without this,
        // stream=false clients sit silent through a full DeepThink run and
        // often hit their own one-minute read timeout.
        let explicit_thinking = match value.get("thinking") {
            Some(Value::Bool(on)) => Some(*on),
            Some(object) => match object.get("type").and_then(Value::as_str) {
                Some("enabled") => Some(true),
                Some("disabled") => Some(false),
                _ => Some(false),
            },
            None => None,
        };
        let requested_effort = value.get("reasoning_effort").and_then(Value::as_str);
        let effort = match requested_effort {
            Some("low") => "low",
            Some("max") => "max",
            _ => "high",
        };
        let thinking = match explicit_thinking {
            Some(on) => on,
            None => match requested_effort {
                Some("none" | "minimal") | None => false,
                Some(_) => true,
            },
        };
        let stream = value.get("stream").and_then(Value::as_bool).unwrap_or(false);

        Ok(Self {
            messages,
            model: model.to_string(),
            thinking,
            effort: effort.to_string(),
            stream,
        })
    }
}

fn web_model(model: &str) -> &'static str {
    if model == "deepseek-v4-pro" {
        "expert"
    } else {
        "default"
    }
}

fn content_text(content: Option<&Value>) -> String {
    match content {
        Some(Value::String(s)) => s.clone(),
        Some(Value::Array(parts)) => parts
            .iter()
            .filter_map(|part| {
                let kind = part.get("type").and_then(Value::as_str).unwrap_or("text");
                if kind == "text" {
                    part.get("text").and_then(Value::as_str)
                } else {
                    None
                }
            })
            .collect::<Vec<_>>()
            .join("\n"),
        _ => String::new(),
    }
}

fn authorized(request: &Request, key: &str) -> bool {
    request
        .headers()
        .iter()
        .find(|h| h.field.equiv("Authorization"))
        .map(|h| h.value.as_str().trim() == format!("Bearer {key}"))
        .unwrap_or(false)
}

fn header(name: &str, value: &str) -> Header {
    Header::from_bytes(name.as_bytes(), value.as_bytes()).expect("static header")
}

fn cors<R: Read>(response: Response<R>) -> Response<R> {
    response
        .with_header(header("Access-Control-Allow-Origin", "*"))
        .with_header(header(
            "Access-Control-Allow-Headers",
            "authorization, content-type",
        ))
        .with_header(header("Access-Control-Allow-Methods", "GET, POST, OPTIONS"))
}

fn json_response(status: u16, value: &Value) -> Response<Cursor<Vec<u8>>> {
    cors(
        Response::from_string(value.to_string())
            .with_status_code(StatusCode(status))
            .with_header(header("Content-Type", "application/json")),
    )
}

fn status_for(error: &Error) -> u16 {
    match error.kind {
        ErrorKind::Unauthorized => 401,
        ErrorKind::InsufficientBalance => 402,
        ErrorKind::RateLimited => 429,
        _ => 502,
    }
}

fn error_body(message: &str) -> Value {
    json!({"error": {"message": message, "type": "invalid_request_error"}})
}

fn new_id() -> String {
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let n = COUNTER.fetch_add(1, Ordering::Relaxed);
    format!("chatcmpl-{:x}{:x}", now_ms(), n)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn parse(extra: Value) -> ChatRequest {
        let mut body = json!({
            "messages": [{"role": "user", "content": "привет"}],
            "model": "deepseek-flash"
        });
        if let (Some(target), Some(source)) = (body.as_object_mut(), extra.as_object()) {
            for (key, value) in source {
                target.insert(key.clone(), value.clone());
            }
        }
        ChatRequest::parse(&body).expect("valid request")
    }

    #[test]
    fn local_api_reasoning_is_opt_in() {
        assert!(!parse(json!({})).thinking, "default must stay fast");
        assert!(!parse(json!({"thinking": false})).thinking);
        assert!(parse(json!({"thinking": true})).thinking);
        assert!(parse(json!({"thinking": {"type": "enabled"}})).thinking);
        assert!(!parse(json!({"thinking": {"type": "disabled"}})).thinking);
        assert!(parse(json!({"reasoning_effort": "high"})).thinking);
        assert!(parse(json!({"reasoning_effort": "max"})).thinking);
        assert_eq!(parse(json!({"reasoning_effort": "max"})).effort, "max");
        assert!(parse(json!({"reasoning_effort": "low"})).thinking);
        assert_eq!(parse(json!({"reasoning_effort": "low"})).effort, "low");
        assert!(!parse(json!({"reasoning_effort": "none"})).thinking);
        assert_eq!(
            parse(json!({"thinking": {"type": "enabled"}, "reasoning_effort": "low"})).effort,
            "low"
        );
    }
}
